(7032694, 1068288, 30861, '<td valign="top">Dead flies rest for a "moment"? Jejeje... Pretty picture, though :-)</td>', 'Dead flies rest for a "moment"? Jejeje... Pretty picture, though :-)', '2013-05-06 01:15:26.000000', NULL, 1),
(7032697, 1068372, 96751, '<td valign="top">Like a flower. I don''t think she should have been looking at the camera, though. From this pov, her face is strained, and works against the grace of the image.</td>', 'Like a flower. I don''t think she should have been looking at the camera, though. From this pov, her face is strained, and works against the grace of the image.', '2013-05-06 01:16:22.000000', NULL, 1),
(7032700, 1068419, 96751, '<td valign="top">Superb!</td>', 'Superb!', '2013-05-06 01:17:11.000000', NULL, 1),
(7032705, 1068494, 96751, '<td valign="top">Nicely done! Oddly gigantic legs on a tiny upper body :-)</td>', 'Nicely done! Oddly gigantic legs on a tiny upper body :-)', '2013-05-06 01:18:31.000000', NULL, 1),
(7032706, 1068322, 96751, '<td valign="top">Elegant and geometric</td>', 'Elegant and geometric', '2013-05-06 01:19:15.000000', NULL, 1),
