(7032745, 1068400, 96751, '<td valign="top">There are several rather odd things about this image, including how different her two eyes are. But mostly, I don''t see this as a clear example of perspective.</td>', 'There are several rather odd things about this image, including how different her two eyes are. But mostly, I don''t see this as a clear example of perspective.', '2013-05-06 01:41:54.000000', NULL, 1),
(7032746, 1068424, 96751, '<td valign="top">Lovely glow</td>', 'Lovely glow', '2013-05-06 01:42:08.000000', NULL, 1),
(7032747, 1068543, 96751, '<td valign="top">This is a wonderful example of how perspective makes you stop and try to figure out what you''re looking at!</td>', 'This is a wonderful example of how perspective makes you stop and try to figure out what you''re looking at!', '2013-05-06 01:42:36.000000', NULL, 1),
(7032748, 1068422, 96751, '<td valign="top">Love it! Nice, menacing mood achieved</td>', 'Love it! Nice, menacing mood achieved', '2013-05-06 01:43:19.000000', NULL, 1),
(7032750, 1068162, 96751, '<td valign="top">Very cool architecture. This reminds me of Brent''s work.</td>', 'Very cool architecture. This reminds me of Brent''s work.', '2013-05-06 01:43:49.000000', NULL, 1),
(7032751, 1068533, 96751, '<td valign="top">Well positioned for this shot. Was it raining, or did you somehow manage to capture stars as well????</td>', 'Well positioned for this shot. Was it raining, or did you somehow manage to capture stars as well????', '2013-05-06 01:44:33.000000', NULL, 1),
(7032752, 1068417, 96751, '<td valign="top">Wonderful!!!I love how organic these bunched up q-tips look. Great dof as well</td>', 'Wonderful!!!I love how organic these bunched up q-tips look. Great dof as well', '2013-05-06 01:44:57.000000', NULL, 1),
(7032753, 1067801, 96751, '<td valign="top">Lovely image. Love the diagonals</td>', 'Lovely image. Love the diagonals', '2013-05-06 01:45:16.000000', NULL, 1),
(7032754, 1068488, 96751, '<td valign="top">To me, this is more about a sense of scale than of perspective. Impressive capture, regardless.</td>', 'To me, this is more about a sense of scale than of perspective. Impressive capture, regardless.', '2013-05-06 01:45:41.000000', NULL, 1),
(7032755, 1068512, 96751, '<td valign="top">Riley sure has big feet</td>', 'Riley sure has big feet', '2013-05-06 01:46:15.000000', NULL, 1),
(7032756, 1068480, 123833, '<td valign="top">Nice PP and light</td>', 'Nice PP and light', '2013-05-06 01:46:37.000000', NULL, 1),
(7032757, 1068203, 96751, '<td valign="top">The light is gorgeous. I feel there is too much red in this image, and although a glorious landscape, I don''t see this as an example of perspective</td>', 'The light is gorgeous. I feel there is too much red in this image, and although a glorious landscape, I don''t see this as an example of perspective', '2013-05-06 01:47:11.000000', NULL, 1),
