(7032796, 1068494, 49109, '<td valign="top">Good idea and well executed, but totally wrong props. Hitting off a tee with a driver from the rough? Absurd.</td>', 'Good idea and well executed, but totally wrong props. Hitting off a tee with a driver from the rough? Absurd.', '2013-05-06 04:30:02.000000', NULL, 1),
(7032797, 1068259, 108580, '<td valign="top">Amazing engineering, photographed with an interesting perspective and UWA to emphasise this.</td>', 'Amazing engineering, photographed with an interesting perspective and UWA to emphasise this.', '2013-05-06 04:31:49.000000', NULL, 1),
(7032798, 1067801, 108580, '<td valign="top">Lovely rural sight photographed with an interesting perspective to emphasise triangulation and disappearing lines.</td>', 'Lovely rural sight photographed with an interesting perspective to emphasise triangulation and disappearing lines.', '2013-05-06 04:34:24.000000', NULL, 1),
(7032799, 1068276, 108580, '<td valign="top">Ample lines emphasising convergence and perspective. Warm PP.</td>', 'Ample lines emphasising convergence and perspective. Warm PP.', '2013-05-06 04:35:17.000000', NULL, 1),
(7032801, 1068408, 108580, '<td valign="top">Aerial vantage point photographed with an unique perspective and WA to emphasise this. Nice tones.</td>', 'Aerial vantage point photographed with an unique perspective and WA to emphasise this. Nice tones.', '2013-05-06 04:42:05.000000', NULL, 1),
(7032805, 1068377, 108580, '<td valign="top">Convergence and perspective, good PP. DMC</td>', 'Convergence and perspective, good PP. DMC', '2013-05-06 04:55:55.000000', NULL, 1),
(7032809, 1068480, 108580, '<td valign="top">Perfect converging lines and perspective. DMC. Good PP.</td>', 'Perfect converging lines and perspective. DMC. Good PP.', '2013-05-06 05:17:24.000000', NULL, 1),
(7032810, 1068424, 108580, '<td valign="top">Perfect converging railway lines and low to high perspective. DMC. Good PP.</td>', 'Perfect converging railway lines and low to high perspective. DMC. Good PP.', '2013-05-06 05:18:37.000000', NULL, 1),
(7032811, 1068531, 108580, '<td valign="top">Perfect converging building lines and low to high perspective. DMC. Great reflection but a little subdued in contrast and colour.</td>', 'Perfect converging building lines and low to high perspective. DMC. Great reflection but a little subdued in contrast and colour.', '2013-05-06 05:20:05.000000', NULL, 1),
