(7036458, 1068162, 97225, '<td valign="top">Congrats on the HM Oliver. Great shot and awesome architecture.</td>', 'Congrats on the HM Oliver. Great shot and awesome architecture.', '2013-05-13 09:09:49.000000', NULL, 0),
(7036459, 1068494, 97225, '<td valign="top">Congrats on the ribbon. Cool shot.</td>', 'Congrats on the ribbon. Cool shot.', '2013-05-13 09:11:11.000000', NULL, 0),
(7036460, 1068533, 97225, '<td valign="top">Congrats on the red Christophe. I love that fish eye perspective and the colours are lovely - they glow.</td>', 'Congrats on the red Christophe. I love that fish eye perspective and the colours are lovely - they glow.', '2013-05-13 09:13:31.000000', NULL, 0),
(7036461, 1068308, 97225, '<td valign="top">Fascinating place. Congrats on the TT finish.</td>', 'Fascinating place. Congrats on the TT finish.', '2013-05-13 09:15:08.000000', NULL, 0),
(7036463, 1068322, 92577, '<td valign="top">Grats on the TT. You <b>own</b> <a href="//www.dpchallenge.com/camera.php?CAMERA_ID=2213" rel="nofollow" target="_blank">this page.</a></td>', 'Grats on the TT. You own this page.', '2013-05-13 09:27:28.000000', NULL, 0),
(7036464, 1068541, 114969, '<td valign="top">Shooting trees is very hard according to my own experience. I spent a full day shooting hundreds of photos before giving up, and going for an architecture shot instead. However, you did a great job and succeeded in this difficult task. I love the crazy shapes of the branches against the perfectly exposed sky, very pleasant to look at. Wonderfully done.</td>', 'Shooting trees is very hard according to my own experience. I spent a full day shooting hundreds of photos before giving up, and going for an architecture shot instead. However, you did a great job and succeeded in this difficult task. I love the crazy shapes of the branches against the perfectly exposed sky, very pleasant to look at. Wonderfully done.', '2013-05-13 09:34:48.000000', NULL, 0),
(7036466, 1068494, 92577, '<td valign="top">great fun shot and hard work rewarded. congrats</td>', 'great fun shot and hard work rewarded. congrats', '2013-05-13 09:38:18.000000', NULL, 0),
